(function () {
  'use strict';
  // True APR including fees (US Truth in Lending, actuarial method, monthly payments).
  //   Balance B = loan amount + fees added to the loan.  Payment M = B * i / (1 - (1 + i)^-n),
  //   i = note rate / 12 (M = B / n at 0%).  Amount financed A = loan amount - upfront fees - points.
  //   APR = 12 * j, where j solves A = M * (1 - (1 + j)^-n) / j  (bisection, 200 halvings).
  //   Finance charge = M * n - A.  Effective annual rate of the APR = (1 + j)^12 - 1.
  // Verified in Node (scratchpad tests/w2loans): $100,000 at 6% for 10 years with $2,500 upfront
  //   fees -> payment $1,110.21, APR 6.563%; $280,000 at 6.2% for 30 years with $3,500 fees and
  //   0.5 points -> payment $1,714.91, APR 6.367% (both match a published APR calculator's
  //   defaults); no fees -> APR equals the note rate; 0% with fees gives a positive APR; blank,
  //   negative and fees >= loan show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  function pv(pmt, j, n) { return j === 0 ? pmt * n : pmt * (1 - Math.pow(1 + j, -n)) / j; }

  // Monthly rate j at which n payments of pmt are worth exactly the amount financed.
  function solveMonthly(net, pmt, n) {
    if (net <= 0 || pmt <= 0) return NaN;
    if (net >= pmt * n - 1e-9) return 0;
    var lo = 0, hi = 1;
    while (pv(pmt, hi, n) > net && hi < 1e6) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pv(pmt, mid, n) > net) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['apApr', 'apPayment', 'apCharge', 'apRateOut', 'apSpread', 'apNet', 'apBalance', 'apFeesOut', 'apInterest', 'apTotal', 'apEar']
      .forEach(function (id) { setText(id, '–'); });
  }

  function update() {
    var amount = read('apAmount'), rate = read('apRate'), years = read('apYears', true), months = read('apMonths', true),
        fees = read('apFees', true), points = read('apPoints', true), financed = read('apFinanced', true);
    var error = el('apError'), msg = '';
    var n = years * 12 + months;
    if (isNaN(amount) || amount <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (isNaN(years) || isNaN(months) || years < 0 || months < 0 || years % 1 !== 0 || months % 1 !== 0 || years > 50 || months > 11)
      msg = 'Enter the term as whole years (0 to 50) and months (0 to 11).';
    else if (n < 1) msg = 'Enter a loan term of at least one month.';
    else if ([fees, points, financed].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Fees and points cannot be negative.';
    else if (points > 10) msg = 'Enter 10 points or fewer.';
    var pointsCost = amount * points / 100;
    var net = amount - fees - pointsCost;
    if (!msg && net <= 0) msg = 'Upfront fees and points must be less than the loan amount.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var balance = amount + financed;
    var pmt = payment(balance, rate / 100 / 12, n);
    var total = pmt * n;
    var j = solveMonthly(net, pmt, n);
    if (isNaN(j)) { clearResults(); return; }
    var apr = 12 * j;
    setText('apApr', (apr * 100).toFixed(3) + '%');
    setText('apPayment', money.format(pmt));
    setText('apCharge', money.format(total - net));
    setText('apRateOut', rate.toFixed(3) + '%');
    setText('apSpread', ((apr * 100 - rate) >= 0 ? '+' : '') + (apr * 100 - rate).toFixed(3) + ' percentage points');
    setText('apNet', money.format(net));
    setText('apBalance', money.format(balance));
    setText('apFeesOut', money.format(fees + pointsCost + financed));
    setText('apInterest', money.format(total - balance));
    setText('apTotal', money.format(total));
    setText('apEar', (Math.pow(1 + j, 12) * 100 - 100).toFixed(3) + '%');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('apForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
